/**
 * Package-manager manifests (Scoop, winget, AUR), regenerated by the release
 * script for each version with the real SHA-256 checksums.
 */
import { mkdir, rm } from "node:fs/promises";
import { join } from "node:path";

const REPO = "OctavianAdv/helium-drm-fixer";
const URL = `https://github.com/${REPO}`;
const DESCRIPTION = "Fix DRM (Widevine) in the Helium browser on Windows and Linux";
const LONG_DESCRIPTION =
  "Finds Widevine in your other browsers and apps (or downloads it from Google), installs it into Helium in the layout Helium expects, and verifies inside Helium that DRM works.";

export type Checksums = Record<string, string>;

function download(version: string, asset: string): string {
  return `${URL}/releases/download/v${version}/${asset}`;
}

function scoop(version: string, sums: Checksums): string {
  return JSON.stringify(
    {
      version,
      description: DESCRIPTION,
      homepage: URL,
      license: "MIT",
      architecture: {
        "64bit": {
          url: `${download(version, "fix-helium-drm-windows-x64.exe")}#/fix-helium-drm.exe`,
          hash: sums["fix-helium-drm-windows-x64.exe"],
        },
      },
      bin: "fix-helium-drm.exe",
      checkver: { github: URL },
      autoupdate: {
        architecture: {
          "64bit": { url: `${URL}/releases/download/v$version/fix-helium-drm-windows-x64.exe#/fix-helium-drm.exe` },
        },
        hash: { url: "$baseurl/SHA256SUMS.txt" },
      },
    },
    null,
    4
  ) + "\n";
}

function winget(version: string, sums: Checksums): Record<string, string> {
  const id = "OctavianAdv.HeliumDrmFixer";
  const head = `# yaml-language-server: $schema=https://aka.ms/winget-manifest.{type}.1.6.0.schema.json\n\nPackageIdentifier: ${id}\nPackageVersion: ${version}\n`;
  return {
    [`${id}.yaml`]: head.replace("{type}", "version") + "DefaultLocale: en-US\nManifestType: version\nManifestVersion: 1.6.0\n",
    [`${id}.installer.yaml`]:
      head.replace("{type}", "installer") +
      `InstallerType: portable\nCommands:\n- fix-helium-drm\nInstallers:\n- Architecture: x64\n  InstallerUrl: ${download(version, "fix-helium-drm-windows-x64.exe")}\n  InstallerSha256: ${sums["fix-helium-drm-windows-x64.exe"]!.toUpperCase()}\nManifestType: installer\nManifestVersion: 1.6.0\n`,
    [`${id}.locale.en-US.yaml`]:
      head.replace("{type}", "defaultLocale") +
      `PackageLocale: en-US\nPublisher: OctavianAdv\nPublisherUrl: https://github.com/OctavianAdv\nPackageName: Helium DRM Fixer\nPackageUrl: ${URL}\nLicense: MIT\nLicenseUrl: ${URL}/blob/main/LICENSE.md\nShortDescription: ${DESCRIPTION}\nDescription: ${LONG_DESCRIPTION}\nTags:\n- helium\n- drm\n- widevine\n- browser\nReleaseNotesUrl: ${URL}/releases/tag/v${version}\nManifestType: defaultLocale\nManifestVersion: 1.6.0\n`,
  };
}

function pkgbuild(version: string, sums: Checksums): string {
  return `# Maintainer: OctavianAdv <https://github.com/OctavianAdv>
pkgname=helium-drm-fixer-bin
pkgver=${version}
pkgrel=1
pkgdesc="${DESCRIPTION}"
arch=('x86_64' 'aarch64')
url="${URL}"
license=('MIT')
provides=('helium-drm-fixer')
conflicts=('helium-drm-fixer')
depends=('tar' 'xz')
# Bun single-file executables must not be stripped
options=('!strip' '!debug')
source_x86_64=("fix-helium-drm-\${pkgver}-x86_64::\${url}/releases/download/v\${pkgver}/fix-helium-drm-linux-x64")
source_aarch64=("fix-helium-drm-\${pkgver}-aarch64::\${url}/releases/download/v\${pkgver}/fix-helium-drm-linux-arm64")
sha256sums_x86_64=('${sums["fix-helium-drm-linux-x64"]}')
sha256sums_aarch64=('${sums["fix-helium-drm-linux-arm64"]}')

package() {
  install -Dm755 "\${srcdir}/fix-helium-drm-\${pkgver}-\${CARCH}" "\${pkgdir}/usr/bin/fix-helium-drm"
}
`;
}

function srcinfo(version: string, sums: Checksums): string {
  return `pkgbase = helium-drm-fixer-bin
\tpkgdesc = ${DESCRIPTION}
\tpkgver = ${version}
\tpkgrel = 1
\turl = ${URL}
\tarch = x86_64
\tarch = aarch64
\tlicense = MIT
\tdepends = tar
\tdepends = xz
\tprovides = helium-drm-fixer
\tconflicts = helium-drm-fixer
\toptions = !strip
\toptions = !debug
\tsource_x86_64 = fix-helium-drm-${version}-x86_64::${download(version, "fix-helium-drm-linux-x64")}
\tsha256sums_x86_64 = ${sums["fix-helium-drm-linux-x64"]}
\tsource_aarch64 = fix-helium-drm-${version}-aarch64::${download(version, "fix-helium-drm-linux-arm64")}
\tsha256sums_aarch64 = ${sums["fix-helium-drm-linux-arm64"]}

pkgname = helium-drm-fixer-bin
`;
}

export async function writePackaging(root: string, version: string, sums: Checksums): Promise<void> {
  const dir = join(root, "packaging");

  await mkdir(join(dir, "scoop"), { recursive: true });
  await Bun.write(join(dir, "scoop", "helium-drm-fixer.json"), scoop(version, sums));

  const wingetDir = join(dir, "winget");
  await rm(wingetDir, { recursive: true, force: true });
  await mkdir(wingetDir, { recursive: true });
  for (const [name, content] of Object.entries(winget(version, sums))) {
    await Bun.write(join(wingetDir, name), content);
  }

  await mkdir(join(dir, "aur"), { recursive: true });
  await Bun.write(join(dir, "aur", "PKGBUILD"), pkgbuild(version, sums));
  await Bun.write(join(dir, "aur", ".SRCINFO"), srcinfo(version, sums));
}
